            reverted = true;
        }

        uint256 b0 = c.balanceOf(a0, id0);
        uint256 b1 = c.balanceOf(a1, id1);

        assert(
            !reverted &&
            result.length == 2 &&
            result[0] == b0 &&
            result[1] == b1
        );
    }
}

